import React from "react";

export default function TableView({ rows = [] }) {
  if (!rows || rows.length === 0) return <div>No rows</div>;
  const cols = Object.keys(rows[0]);
  const downloadCsv = () => {
    const csvRows = [cols.join(",")].concat(rows.map(r => cols.map(c => `"${String(r[c]).replace(/"/g,'""')}"`).join(",")));
    const blob = new Blob([csvRows.join("\n")], { type: "text/csv" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url; a.download = "filtered.csv"; a.click();
    URL.revokeObjectURL(url);
  };

  return (
    <div>
      <button className="btn btn-sm btn-outline-success mb-2" onClick={downloadCsv}>Download Data</button>
      <div style={{maxHeight:240, overflow:"auto"}}>
        <table className="table table-sm">
          <thead><tr>{cols.map(c => <th key={c}>{c}</th>)}</tr></thead>
          <tbody>
            {rows.map((r, i) => <tr key={i}>{cols.map(c => <td key={c}>{String(r[c])}</td>)}</tr>)}
          </tbody>
        </table>
      </div>
    </div>
  );
}
